namespace app\services;
require_once __DIR__.'/CompanyAsaasRefundPostings.php';require_once __DIR__.'/CompanyInvoiceBalance.php';require_once __DIR__.'/CompanyFinancialJournal.php';
/** Canonical local financial writer. Never executes a refund, creates a credit note, or reverses fees. */
trait CompanyAsaasRefundWriter
{
    public function recordCompanyAsaasFullRefund($issuer,$actor,\Asaas\ConfirmedFullRefund $source):string
    {
        if(get_class($source)!=='Asaas\\ConfirmedFullRefund')throw new \DomainException('company_asaas_full_refund_source_denied');$issuer=\IssuerPolicy::id($issuer);$actor=\IssuerPolicy::id($actor);$p=db_prefix();$source->assertSchema($this->db,$p);$store=new \CompanyAsaasRefundPostings($this->db,$p);$balances=new \CompanyInvoiceBalance($this->db,$p);$journal=new \CompanyFinancialJournal($this->db,$p);$tables=array_values(array_unique(array_merge($source->tables(),$balances->tables(),$journal->tables('payment'),(new \CompanyCurrencyUnits($this->db,$p))->tables())));
        return \IssuerTransaction::run($this->db,$p,$tables,function()use($issuer,$actor,$p,$source,$store,$balances,$journal){$acl=new \IssuerResourceAccess($this->db,$p);$acl->lockFinancialIdentity($issuer,$actor);$claim=$source->claim($this->db,$p,$issuer,$actor);$invoice=\IssuerPolicy::id($claim['invoice']);$payment=\IssuerPolicy::id($claim['payment']);$dto=$claim['reversal'];if(!$dto instanceof \CompanyAsaasRefundData)throw new \DomainException('company_asaas_full_refund_source_denied');$data=$dto->data();$key=\CompanyAsaasRefundPostings::key($issuer,$payment,$data['original_receipt_key']);if($claim['key']!==$key)throw new \DomainException('company_asaas_full_refund_source_denied');$old=$store->capturedInOwned($issuer,$actor,$invoice,$payment);if($old){if(!hash_equals($old->fingerprint(),$dto->fingerprint()))throw new \DomainException('company_asaas_full_refund_conflict');return $key;}
        $before=$balances->inOwned($issuer,$actor,$invoice);$parent=\IssuerStorage::query($this->db,'SELECT currency,status,duedate FROM '.$p.'invoices WHERE id=? AND issuer_id=? FOR UPDATE',[$invoice,$issuer])->row_array();if(!$parent||!in_array((int)$parent['status'],[2,3],true))throw new \DomainException('company_asaas_full_refund_invoice_review');$unit=(new \CompanyCurrencyUnits($this->db,$p))->assertWrite($parent['currency']);if($unit['iso_code']!==$data['currency'])throw new \DomainException('company_asaas_full_refund_original_review');$cash=\CompanyInvoiceAmounts::minor($dto->cashPrincipal());$left=\CompanyInvoiceAmounts::minor($before['receivable']);$total=\CompanyInvoiceAmounts::minor($before['total']);if($cash>\CompanyInvoiceAmounts::minor($before['received'])||$left+$cash>$total)throw new \DomainException('company_asaas_full_refund_balance_review');if(!$store->recordInOwned($issuer,$actor,$invoice,$payment,$dto))throw new \DomainException('company_asaas_full_refund_conflict');$after=$balances->inOwned($issuer,$actor,$invoice,false);if(\CompanyInvoiceAmounts::minor($after['receivable'])!==$left+$cash||\CompanyInvoiceAmounts::minor($before['received'])-\CompanyInvoiceAmounts::minor($after['received'])!==$cash)throw new \DomainException('company_asaas_full_refund_balance_review');$remaining=\CompanyInvoiceAmounts::minor($after['receivable']);$status=$remaining===0?2:($remaining<$total?3:(!empty($parent['duedate'])&&$parent['duedate']<gmdate('Y-m-d')?4:1));\IssuerStorage::query($this->db,'UPDATE '.$p.'invoices SET status=? WHERE id=? AND issuer_id=?',[$status,$invoice,$issuer]);$confirmed=$balances->inOwned($issuer,$actor,$invoice);if($confirmed['receivable']!==$after['receivable'])throw new \RuntimeException('issuer_asaas_full_refund_unconfirmed');
        $journal->recordInOwned($issuer,$actor,['kind'=>'asaas_full_refund_declared','source_type'=>'payment','source_id'=>$payment,'book_date'=>$data['book_date'],'currency'=>$unit['iso_code'],'currency_basis'=>$unit['basis'],'amount'=>$dto->cashPrincipal(),'before'=>['invoice_balance'=>$before['receivable'],'received_principal'=>$before['received']],'after'=>['invoice_balance'=>$confirmed['receivable'],'received_principal'=>$confirmed['received'],'reversal'=>$data]],hash('sha256','company-journal:asaas-full-refund:'.$key));$source->applied($this->db,$p,$issuer,$actor,$key);return $key;});
    }
}
